CREATE TYPE "GmailConnectionStatus" AS ENUM ('CONNECTED', 'RECONNECT_REQUIRED', 'DISCONNECTED');
CREATE TYPE "EmailProcessingStatus" AS ENUM ('NOT_ANALYZED', 'PARSE_PARTIAL', 'PARSE_FAILED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT, "email" TEXT, "emailVerified" TIMESTAMP(3), "image" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Account" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "provider" TEXT NOT NULL, "providerAccountId" TEXT NOT NULL, "refresh_token" TEXT, "access_token" TEXT, "expires_at" INTEGER, "token_type" TEXT, "scope" TEXT, "id_token" TEXT, "session_state" TEXT, CONSTRAINT "Account_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "sessionToken" TEXT NOT NULL, "userId" TEXT NOT NULL, "expires" TIMESTAMP(3) NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "VerificationToken" ("identifier" TEXT NOT NULL, "token" TEXT NOT NULL, "expires" TIMESTAMP(3) NOT NULL);
CREATE TABLE "GmailConnection" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "mailboxEmail" TEXT NOT NULL, "accessTokenEncrypted" TEXT, "refreshTokenEncrypted" TEXT, "tokenExpiresAt" TIMESTAMP(3), "status" "GmailConnectionStatus" NOT NULL DEFAULT 'CONNECTED', "historyId" TEXT, "continuationPageToken" TEXT, "pendingHistoryId" TEXT, "pendingMessageIds" JSONB NOT NULL DEFAULT '[]', "syncInProgress" BOOLEAN NOT NULL DEFAULT false, "lastSyncAt" TIMESTAMP(3), "lastErrorCode" TEXT, "lastErrorMessage" TEXT, "connectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GmailConnection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StoredEmail" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "gmailConnectionId" TEXT NOT NULL, "gmailMessageId" TEXT NOT NULL, "gmailThreadId" TEXT, "sender" TEXT, "replyTo" TEXT, "recipients" JSONB NOT NULL, "subject" TEXT, "receivedAt" TIMESTAMP(3), "plainTextBody" TEXT NOT NULL, "extractedLinks" JSONB NOT NULL, "selectedHeaders" JSONB NOT NULL, "processingStatus" "EmailProcessingStatus" NOT NULL DEFAULT 'NOT_ANALYZED', "contentTruncated" BOOLEAN NOT NULL DEFAULT false, "parseNote" TEXT, "importedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StoredEmail_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmailAttachment" ("id" TEXT NOT NULL, "storedEmailId" TEXT NOT NULL, "fileName" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "sizeBytes" INTEGER NOT NULL, CONSTRAINT "EmailAttachment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Account_provider_providerAccountId_key" ON "Account"("provider", "providerAccountId");
CREATE INDEX "Account_userId_idx" ON "Account"("userId");
CREATE UNIQUE INDEX "Session_sessionToken_key" ON "Session"("sessionToken");
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE UNIQUE INDEX "VerificationToken_identifier_token_key" ON "VerificationToken"("identifier", "token");
CREATE UNIQUE INDEX "GmailConnection_userId_key" ON "GmailConnection"("userId");
CREATE UNIQUE INDEX "GmailConnection_mailboxEmail_key" ON "GmailConnection"("mailboxEmail");
CREATE UNIQUE INDEX "StoredEmail_gmailConnectionId_gmailMessageId_key" ON "StoredEmail"("gmailConnectionId", "gmailMessageId");
CREATE INDEX "StoredEmail_userId_expiresAt_idx" ON "StoredEmail"("userId", "expiresAt");
CREATE INDEX "StoredEmail_gmailConnectionId_receivedAt_idx" ON "StoredEmail"("gmailConnectionId", "receivedAt");
CREATE INDEX "EmailAttachment_storedEmailId_idx" ON "EmailAttachment"("storedEmailId");
ALTER TABLE "Account" ADD CONSTRAINT "Account_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "GmailConnection" ADD CONSTRAINT "GmailConnection_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StoredEmail" ADD CONSTRAINT "StoredEmail_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StoredEmail" ADD CONSTRAINT "StoredEmail_gmailConnectionId_fkey" FOREIGN KEY ("gmailConnectionId") REFERENCES "GmailConnection"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EmailAttachment" ADD CONSTRAINT "EmailAttachment_storedEmailId_fkey" FOREIGN KEY ("storedEmailId") REFERENCES "StoredEmail"("id") ON DELETE CASCADE ON UPDATE CASCADE;
